const fs = require("fs");
const path = require("path");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
(async () => {
  const tw = require("tailwindcss");
  const dir = path.dirname(require.resolve("tailwindcss/package.json"));
  const files = { "tailwindcss": "index.css", "tailwindcss/theme.css": "theme.css", "tailwindcss/utilities.css": "utilities.css", "tailwindcss/preflight.css": "preflight.css" };
  const loadStylesheet = async (id) => {
    const f = files[id];
    if (!f) throw new Error("unexpected stylesheet " + id);
    const p = path.join(dir, f);
    return { path: p, base: path.dirname(p), content: fs.readFileSync(p, "utf8") };
  };
  let ds;
  try { ds = await tw.__unstable__loadDesignSystem("@import \"tailwindcss\";", { base: dir, loadStylesheet }); }
  catch (e) { broken("could not load the design system: " + e.message); }
  if (typeof ds.canonicalizeCandidates !== "function") broken("canonicalizeCandidates is missing");
  const ctl = ds.canonicalizeCandidates(["order-none"]);
  if (ctl.length !== 1 || ctl[0] !== "order-0") broken("control order-none canonicalized to " + JSON.stringify(ctl));
  const out = ds.canonicalizeCandidates(["overflow-ellipsis"]);
  if (out.length !== 1) broken("unexpected result " + JSON.stringify(out));
  if (out[0] === "overflow-ellipsis") symptom("canonicalizeCandidates leaves overflow-ellipsis unchanged instead of text-ellipsis");
  if (out[0] !== "text-ellipsis") broken("overflow-ellipsis canonicalized to " + out[0]);
  console.log("OK: canonicalizeCandidates turns overflow-ellipsis into text-ellipsis");
})().catch((e) => broken(String(e && e.stack || e)));

